<section class="vc-page-actions"><div><span class="vc-status info" id="vsi-status">Loading impact evidence…</span></div></section>
<div class="vc-grid two"><section class="vc-card"><div class="vc-card-head"><h2>Submit a sustainability claim</h2></div><form class="vc-card-body" id="vsi-claim"><div class="vc-field"><label>Claim statement</label><textarea class="vc-textarea" name="claim_statement" minlength="20" maxlength="2000" required rows="4" placeholder="A specific, measurable claim about your product or process"></textarea></div><div class="vc-field"><label>Scope</label><input class="vc-input" name="scope" required minlength="2" maxlength="180" placeholder="Which products or processes does it cover?"></div><div class="vc-field"><label>Claim type</label><select class="vc-select" name="claim_type"><option>Materials</option><option>Packaging</option><option>Craft process</option><option>Social impact</option><option>Other measurable claim</option></select></div><div class="vc-field"><label>Evidence issuer or source</label><input class="vc-input" name="issuer" required minlength="2" maxlength="180"></div><div class="vc-field"><label>Evidence type</label><input class="vc-input" name="evidence_type" required maxlength="120" placeholder="Certificate, sourcing record, audit…"></div><div class="vc-field"><label>Limitations or exclusions</label><textarea class="vc-textarea" name="limitations" minlength="10" maxlength="1000" required rows="3"></textarea></div><div class="vc-field"><label>Review by date</label><input class="vc-input" name="valid_until" type="date" required></div><div class="vc-field"><label>Evidence file</label><input class="vc-input" name="evidence" type="file" accept="application/pdf,image/jpeg,image/png" required></div><p class="vc-help">Claims remain hidden until evidence is scanned and approved. Do not claim certification unless it is current and supported.</p><button class="vc-btn primary" type="submit">Submit claim for review</button></form></section>
<section class="vc-card"><div class="vc-card-head"><h2>Upload a certificate</h2></div><form class="vc-card-body" id="vsi-certificate"><div class="vc-field"><label>Certificate type</label><input class="vc-input" name="certificate_type" required minlength="2" maxlength="120"></div><div class="vc-field"><label>Issuer</label><input class="vc-input" name="issuer" required minlength="2" maxlength="180"></div><div class="vc-field"><label>Reference number (optional)</label><input class="vc-input" name="reference_number" maxlength="120"></div><div class="vc-field"><label>Valid from</label><input class="vc-input" name="valid_from" type="date"></div><div class="vc-field"><label>Valid until</label><input class="vc-input" name="valid_until" type="date"></div><div class="vc-field"><label>Certificate file</label><input class="vc-input" name="evidence" type="file" accept="application/pdf,image/jpeg,image/png" required></div><button class="vc-btn primary" type="submit">Upload certificate</button></form></section></div>
<div class="vc-grid two mt-3"><section class="vc-card"><div class="vc-card-head"><h2>Submitted claims</h2></div><div class="vc-card-body vc-list" id="vsi-claims">Loading…</div></section><section class="vc-card"><div class="vc-card-head"><h2>Certificates</h2></div><div class="vc-card-body vc-list" id="vsi-certificates">Loading…</div></section></div>
